const slot=optionalSlot<S,A>()('child');const reducer:Reducer<S,A>=(s,a)=>[a.type==='remove'?{child:null}:a.type==='replace'?{child:{value:s.child?.value??0}}:s,Effect.none()];const child:Reducer<{value:number},CA>=s=>[s,Effect.none()];
